// LOW. Native 0x1426b5df0: gets owner charge component, when WeaponState==3 plays charge-start FX (0x1406b5480),
// then marks charging started and moves charge state to 1.
if (AFortPlayerController* OwnerController = Cast<AFortPlayerController>(GetOwner()))
{
    if (WeaponState == 3 && OwnerController->GetChargeComponentForWeapon())
    {
        PlayChargeStartFX();   // 0x1406b5480 (not named)
    }
    if (OwnerController->IsLocalController() || WeaponState == 3)
    {
        bChargeStarted = true;     // byte +0x28a
        SetChargeStatusInternal(1);
    }
}
